"""Stamps every sport folder from template/ + gen_data.py into out/ApexSports/<group>/<sport>/ (and keeps the templates in out/ApexSports/_shared/templates)."""
import json, os, shutil, sys, datetime as dt
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__))); import gen_data as G
HERE = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(HERE, 'out', 'ApexSports'); TPL = os.path.join(HERE, 'template')
FACT = {'football': 'football.py', 'hockey': 'hockey.py', 'basketball': 'basketball.py', 'baseball': 'baseball.py', 'soccer': 'soccer.py', 'afl': 'generic.py', 'rugby': 'generic.py'}
SPEC = '''APEX SPORTS EXPANSION (owner, 11/5/2026 3:22 PM CT): "Every sport must operate as a completely independent system with its own files, databases, collectors, schedulers, models, rules, grading, reports, Discord outputs, and historical data. DO NOT build a universal sports model. DO NOT share projections / databases / historical records / feature weights / training data between sports. The only thing shared across Apex Sports should be the operational workflow and architecture pattern." Discord: one bot per sport (decision card 3:32 PM CT); keys pasted through /bball-sportkey (his 3:37 PM CT ask).'''
def readme(c):
    L = ['# Apex %s %s' % (c['name'], c['emoji']), '', 'Independent Apex Sports system for %s. Own folder, own history.db, own collectors, scheduler, models, rules, grading, reports, Discord bot and logs. It imports nothing from any other sport, from Apex Tennis or from Apex Basketball; the only shared things are two small PrizePicks pacing flags in `../_shared/`.' % c['name'], '',
         '## Pipeline', '', 'FETCH (collectors/collector.py) -> STORE (database/history.db + database/snapshots, append only) -> PROJECT (models/projection.py + models/sport_factors.py) -> PROBABILITY (models/probability.py) -> RULES (rules/rules.py) -> PICKS (picks/pipeline.py) -> DISCORD (discord/bot.py, discord/cards.py, discord/post.py) -> GRADING (grading/results.py, grading/grade.py) -> TRACKING (reports/report.py) -> IMPROVEMENT (backtesting/backtest.py weekly re-fit).', '',
         '## Run', '', '```', 'nohup discord/start.sh >/dev/null 2>&1 &      # scheduler + bot, restarts both; waits for secrets/discord_bot_token.txt', 'python3 collectors/collector.py all          # one pull by hand', 'python3 picks/pipeline.py                    # score + print boards', 'python3 history/build_history.py             # (re)build history from the SportsGameOdds download', 'python3 backtesting/backtest.py              # fit + calibration report into reports/', 'python3 grading/results.py && python3 grading/grade.py', 'python3 reports/report.py daily|weekly|monthly|season', '```', '',
         '## Discord', '', 'Channels: ' + ', '.join('#%s-%s' % (c['prefix'], k) for k in ('picks', 'alerts', 'general', 'learning-channel', 'system', 'pnl', 'slips')) + '. Commands: ' + ', '.join('/%s-%s' % (c['prefix'], k) for k in ('fetch', 'top3', 'elite5', 'elite6', 'top10', 'bestgoblin', 'beststandard', 'bestdemon', 'backups', 'picks', 'allprops', 'pnl', 'status', 'ban', 'unban', 'setkey')) + '.', 'Token: paste it in the basketball Discord with /bball-sportkey (sport %s, Discord bot token). Odds API key: /bball-sportkey or /%s-setkey.' % (c['name'], c['prefix']), '',
         '## Stats scored', '', '| stat | PrizePicks names | distribution | on boards |', '|---|---|---|---|']
    for k, s in c['stats'].items(): L.append('| %s | %s | %s | %s |' % (s['label'], ', '.join(n for n, v in c['stats_by_pp_name'].items() if v == k) or '-', s['dist'], 'yes' if s.get('board', True) else 'no (computed, not on a board)'))
    L += ['', '## Factors', '', '**Live now:** ' + '; '.join(c['factors']['live']) + '.', '', '**Pending (no data on this Mac yet):** ' + '; '.join(c['factors']['pending']) + '.', '',
          '## Rules', '', '- Floor %d on Top 3 / Elite 5 / Elite 6 / Top 10 / Best Goblin, 65 on Best Standard, 60 on Best Demon. Tiers A 70+, B 65-69, C 60-64, D under 60.' % c['rules']['floor'], '- Goblin and Demon lines: MORE only. Promo and flash-sale lines off. Banned players off. One pick per game on a numbered board. Players listed Out / Doubtful: no play. Under %d games of history: no play.' % c['rules']['min_games'], '',
          '## Data', '', 'History: SportsGameOdds download leagues %s (`history/build_history.py`). Live lines: PrizePicks league ids %s. Results: ESPN %s. Books: The Odds API %s (needs this sport\'s own key in secrets/).' % (', '.join(c['sgo']['leagues']) or 'none on the Mac', ', '.join('%s=%s' % kv for kv in c['prizepicks']['leagues'].items()) or 'none yet', ', '.join(c['espn']['paths']), ', '.join(c['odds_api']['sport_keys']) or 'none'), '',
          'Everything is 🧪 TEST until owner says otherwise. Nothing goes on a board without his go.']
    return '\n'.join(L)
def stamp(key, c):
    g = c['group']; dest = os.path.join(OUT, g, key) if g != key else os.path.join(OUT, key)
    if os.path.exists(dest): shutil.rmtree(dest)
    shutil.copytree(TPL, dest); shutil.copy(os.path.join(HERE, 'factors', FACT[g]), os.path.join(dest, 'models', 'sport_factors.py'))
    json.dump(c, open(os.path.join(dest, 'config', 'sport.json'), 'w'), indent=1, ensure_ascii=False)
    open(os.path.join(dest, 'README.md'), 'w').write(readme(c))
    open(os.path.join(dest, 'DECISIONS.md'), 'w').write('# Decisions (his words)\n\n' + SPEC + '\n')
    open(os.path.join(dest, 'CHANGELOG.md'), 'w').write('# Changelog\n\n- %s built from the Apex Sports template: collectors, history.db, projection + probability engines, rules, boards, Discord bot, grading, reports, scheduler, backtest.\n' % dt.date.today().isoformat())
    open(os.path.join(dest, 'PLAN.md'), 'w').write('# Plan\n\n1. Collect PrizePicks lines, ESPN schedule/injuries/results every day (scheduler).\n2. History from the SportsGameOdds download; backtest fits the spread scale and line anchor per stat on the first half, checks the second half.\n3. Boards post only after owner\'s go; until then everything is 🧪 TEST in this sport\'s own channels.\n4. Pending factors (README) get wired as a data source appears; each one is backtested alone before it touches a board.\n')
    for d in ('logs', 'cache', 'exports', 'secrets', 'reports', 'database/snapshots'): os.makedirs(os.path.join(dest, d), exist_ok=True); open(os.path.join(dest, d, '.gitkeep'), 'a').close()
    open(os.path.join(dest, '.gitignore'), 'w').write('secrets/*\n!secrets/.gitkeep\ndatabase/history.db*\ndatabase/snapshots/\nlogs/*\n!logs/.gitkeep\ncache/\nexports/\n__pycache__/\n*.pyc\n')
    return dest
if __name__ == '__main__':
    if os.path.exists(OUT): shutil.rmtree(OUT)
    for k, c in G.SPORTS.items(): print(stamp(k, c))
    sh = os.path.join(OUT, '_shared'); os.makedirs(os.path.join(sh, 'templates'), exist_ok=True); shutil.copytree(TPL, os.path.join(sh, 'templates', 'sport'), dirs_exist_ok=True); shutil.copytree(os.path.join(HERE, 'factors'), os.path.join(sh, 'templates', 'factors'), dirs_exist_ok=True)
    shutil.copy(os.path.join(HERE, 'gen_data.py'), os.path.join(sh, 'templates', 'gen_data.py')); shutil.copy(os.path.join(HERE, 'gen.py'), os.path.join(sh, 'templates', 'gen.py'))
    open(os.path.join(sh, 'templates', 'README.md'), 'w').write('# Apex Sports templates\n\nThe pattern every sport was stamped from (11/5/2026). Sports do not import from here; this is the blueprint only. New sport: add it to gen_data.py, run gen.py, copy the folder.\n')
